"""Build stand-alone test simulators (stdlib only) from the installed dev games.

The runner child runs with `python -I -S`, so a simulator must not import arena. This copies a
dev game's game.py, swaps `from arena.core import Game` for a tiny stub base class and appends
the harness simulator contract: `action_report(player_id)`, `Game = <GameClass>`, `selftest()`.

    uv run python tests/fixtures/simgen.py      # rewrites alpha_sim.py and beta_sim.py
"""

import importlib.util
from pathlib import Path

HERE = Path(__file__).parent

_STUB = """
class Game:  # stand-in for arena.core.Game (the simulator must be stdlib only)
    n_players = 2

    def __init__(self, seed=None):
        self.seed = seed

"""

_TAIL = """

# --- harness simulator contract (appended by tests/fixtures/simgen.py) ---


def _hz_action_report(self, player_id):
    return {
        "well_formed": bool(self.action_format_correct_last_turn[player_id]),
        "n_illegal": int(self.n_invalid_actions_last_turn[player_id]),
    }


{cls}.action_report = _hz_action_report
Game = {cls}


def selftest():
    return []
"""


def game_source(game: str) -> str:
    """The installed arena_games_dev.<game>/game.py source, read without importing arena."""
    spec = importlib.util.find_spec("arena_games_dev")
    if spec is None or not spec.submodule_search_locations:
        raise RuntimeError("arena_games_dev is not installed")
    root = Path(next(iter(spec.submodule_search_locations)))
    return (root / game / "game.py").read_text(encoding="utf-8")


def build(game: str, cls: str) -> str:
    src = game_source(game)
    marker = "from arena.core import Game\n"
    if marker not in src:
        raise RuntimeError(f"{game}/game.py no longer imports arena.core.Game as expected")
    header = f"# ruff: noqa\n# GENERATED by tests/fixtures/simgen.py from arena_games_dev.{game}\n"
    return header + src.replace(marker, _STUB) + _TAIL.replace("{cls}", cls)


def write_all() -> list[Path]:
    out = []
    for game, cls in (("alpha", "AlphaGame"), ("beta", "BetaGame")):
        path = HERE / f"{game}_sim.py"
        path.write_text(build(game, cls), encoding="utf-8", newline="\n")
        out.append(path)
    return out


if __name__ == "__main__":
    for p in write_all():
        print(p)
